-- Source: 202610040001_private_groups.sql
-- Private groups and explicitly selected, independent starter trips.
-- Supabase provides auth.users, auth.uid(), anon and authenticated.

create schema if not exists app_private;
revoke all on schema app_private from public, anon, authenticated;
grant usage on schema app_private to authenticated;

create table public.groups (
  id uuid primary key default gen_random_uuid(),
  name text not null check (length(btrim(name)) between 1 and 120),
  created_by uuid not null references auth.users(id),
  created_at timestamptz not null default now()
);
create table public.group_members (
  group_id uuid not null references public.groups(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  role text not null check (role in ('owner','admin','member')),
  joined_at timestamptz not null default now(),
  primary key (group_id,user_id)
);
create unique index group_single_owner on public.group_members(group_id) where role = 'owner';
create index group_members_by_user on public.group_members(user_id,group_id);
create table public.trips (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.groups(id) on delete cascade,
  name text not null check (length(btrim(name)) between 1 and 120),
  currency text not null default 'EUR' check (currency ~ '^[A-Z]{3}$'),
  timezone text not null default 'UTC' check (length(timezone) between 1 and 100),
  details jsonb not null default '{}'::jsonb check (jsonb_typeof(details) = 'object' and octet_length(details::text) <= 524288),
  created_by uuid not null references auth.users(id),
  version integer not null default 1 check (version > 0),
  created_at timestamptz not null default now()
);
create index trips_by_group on public.trips(group_id);
create table public.trip_participants (
  trip_id uuid not null references public.trips(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  status text not null check (status in ('going','undecided','not_going')),
  updated_at timestamptz not null default now(),
  primary key (trip_id,user_id)
);
create table public.trip_stops (
  id uuid primary key default gen_random_uuid(),
  trip_id uuid not null references public.trips(id) on delete cascade,
  name text not null check (length(btrim(name)) between 1 and 120),
  position integer not null default 0 check (position between 0 and 10000),
  version integer not null default 1 check (version > 0),
  created_at timestamptz not null default now(),
  unique (trip_id,id)
);
create table public.activities (
  id uuid primary key default gen_random_uuid(),
  trip_id uuid not null references public.trips(id) on delete cascade,
  stop_id uuid,
  title text not null check (length(btrim(title)) between 1 and 200),
  description text not null default '' check (length(description) <= 20000),
  why_visit text not null default '' check (length(why_visit) <= 10000),
  details jsonb not null default '{}'::jsonb check (jsonb_typeof(details) = 'object' and octet_length(details::text) <= 102400),
  created_by uuid not null default auth.uid() references auth.users(id),
  version integer not null default 1 check (version > 0),
  created_at timestamptz not null default now(),
  foreign key (trip_id,stop_id) references public.trip_stops(trip_id,id)
);
create table public.lodgings (
  id uuid primary key default gen_random_uuid(),
  trip_id uuid not null references public.trips(id) on delete cascade,
  stop_id uuid,
  title text not null check (length(btrim(title)) between 1 and 200),
  description text not null default '' check (length(description) <= 20000),
  details jsonb not null default '{}'::jsonb check (jsonb_typeof(details) = 'object' and octet_length(details::text) <= 102400),
  created_by uuid not null default auth.uid() references auth.users(id),
  version integer not null default 1 check (version > 0),
  created_at timestamptz not null default now(),
  foreign key (trip_id,stop_id) references public.trip_stops(trip_id,id)
);
create table public.transfers (
  id uuid primary key default gen_random_uuid(),
  trip_id uuid not null references public.trips(id) on delete cascade,
  stop_id uuid,
  title text not null check (length(btrim(title)) between 1 and 200),
  description text not null default '' check (length(description) <= 20000),
  details jsonb not null default '{}'::jsonb check (jsonb_typeof(details) = 'object' and octet_length(details::text) <= 102400),
  created_by uuid not null default auth.uid() references auth.users(id),
  version integer not null default 1 check (version > 0),
  created_at timestamptz not null default now(),
  foreign key (trip_id,stop_id) references public.trip_stops(trip_id,id)
);
create index activities_by_trip on public.activities(trip_id);
create index lodgings_by_trip on public.lodgings(trip_id);
create index transfers_by_trip on public.transfers(trip_id);
create table public.group_invitations (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.groups(id) on delete cascade,
  token_hash text not null unique,
  created_by uuid not null references auth.users(id),
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default (now() + interval '7 days'),
  revoked_at timestamptz,
  accepted_at timestamptz,
  accepted_by uuid references auth.users(id),
  check ((accepted_at is null) = (accepted_by is null))
);
create index invitations_by_group on public.group_invitations(group_id);
create table app_private.operations (
  user_id uuid not null references auth.users(id) on delete cascade,
  operation text not null,
  request_id uuid not null,
  arguments jsonb not null,
  result_id uuid not null,
  primary key (user_id,operation,request_id)
);

