create function app_private.bump_version() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.version := old.version + 1;
  return new;
end $$;
create function app_private.validate_timezone() returns trigger
language plpgsql set search_path = '' as $$
begin
  if not exists(select 1 from pg_catalog.pg_timezone_names where name = new.timezone) then
    raise exception 'Invalid timezone' using errcode='22023';
  end if;
  return new;
end $$;
create function app_private.touch_trip() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'DELETE' then
    update public.trips set version=version+1 where id=old.trip_id;
    return old;
  end if;
  update public.trips set version=version+1 where id=new.trip_id;
  return new;
end $$;
create trigger trips_version before update on public.trips for each row execute function app_private.bump_version();
create trigger trips_timezone before insert or update of timezone on public.trips for each row execute function app_private.validate_timezone();
create trigger stops_version before update on public.trip_stops for each row execute function app_private.bump_version();
create trigger activities_version before update on public.activities for each row execute function app_private.bump_version();
create trigger lodgings_version before update on public.lodgings for each row execute function app_private.bump_version();
create trigger transfers_version before update on public.transfers for each row execute function app_private.bump_version();
create trigger stops_touch after insert or update or delete on public.trip_stops for each row execute function app_private.touch_trip();
create trigger activities_touch after insert or update or delete on public.activities for each row execute function app_private.touch_trip();
create trigger lodgings_touch after insert or update or delete on public.lodgings for each row execute function app_private.touch_trip();
create trigger transfers_touch after insert or update or delete on public.transfers for each row execute function app_private.touch_trip();
create trigger participants_touch after insert or update or delete on public.trip_participants for each row execute function app_private.touch_trip();

create function app_private.require_user() returns uuid
language plpgsql stable set search_path = '' as $$
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;
  return auth.uid();
end $$;
create function app_private.lock_member(p_group_id uuid,p_editor boolean default false) returns void
language plpgsql set search_path = '' as $$
declare v_role text;
begin
  perform app_private.require_user();
  select role into v_role from public.group_members where group_id=p_group_id and user_id=auth.uid() for key share;
  if v_role is null or (p_editor and v_role not in ('owner','admin')) then raise exception 'Not authorized' using errcode='42501'; end if;
end $$;
create function app_private.operation_result(p_operation text,p_request_id uuid,p_arguments jsonb) returns uuid
language plpgsql set search_path = '' as $$
declare v_existing app_private.operations;
begin
  perform app_private.require_user();
  if p_request_id is null then raise exception 'Request ID required' using errcode='22023'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(auth.uid()::text || p_operation || p_request_id::text,0));
  select * into v_existing from app_private.operations where user_id=auth.uid() and operation=p_operation and request_id=p_request_id;
  if found then
    if v_existing.arguments is distinct from p_arguments then raise exception 'Request ID reused with different arguments' using errcode='22023'; end if;
    return v_existing.result_id;
  end if;
  return null;
end $$;
create function app_private.save_operation(p_operation text,p_request_id uuid,p_arguments jsonb,p_result_id uuid) returns void
language sql set search_path = '' as $$
  insert into app_private.operations(user_id,operation,request_id,arguments,result_id) values(auth.uid(),p_operation,p_request_id,p_arguments,p_result_id)
$$;

create function public.create_group(p_name text,p_request_id uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid; v_args jsonb := jsonb_build_object('name',p_name);
begin
  v_id := app_private.operation_result('create_group',p_request_id,v_args);
  if v_id is not null then
    if not app_private.is_member(v_id) then raise exception 'Not authorized' using errcode='42501'; end if;
    return v_id;
  end if;
  insert into public.groups(name,created_by) values(btrim(p_name),auth.uid()) returning id into v_id;
  insert into public.group_members(group_id,user_id,role) values(v_id,auth.uid(),'owner');
  perform app_private.save_operation('create_group',p_request_id,v_args,v_id);
  return v_id;
end $$;
create function public.create_trip(p_group_id uuid,p_name text,p_template text,p_request_id uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid; v_args jsonb := jsonb_build_object('group_id',p_group_id,'name',p_name,'template',p_template);
begin
  perform app_private.require_user();
  perform app_private.lock_member(p_group_id,true);
  if p_template is null or p_template not in ('blank','china') then raise exception 'Invalid template' using errcode='22023'; end if;
  v_id := app_private.operation_result('create_trip',p_request_id,v_args);
  if v_id is not null then return v_id; end if;
  insert into public.trips(group_id,name,created_by) values(p_group_id,btrim(p_name),auth.uid()) returning id into v_id;
  insert into public.trip_participants(trip_id,user_id,status) values(v_id,auth.uid(),'going');
  if p_template='china' then
    insert into public.trip_stops(trip_id,name,position) values(v_id,'Σαγκάη',0),(v_id,'Πεκίνο',1);
  end if;
  perform app_private.save_operation('create_trip',p_request_id,v_args,v_id);
  return v_id;
end $$;
create function public.create_invitation(p_group_id uuid) returns text
language plpgsql security definer set search_path = '' as $$
declare v_token text;
begin
  perform app_private.require_user();
  perform app_private.lock_member(p_group_id,true);
  v_token := replace(gen_random_uuid()::text,'-','') || replace(gen_random_uuid()::text,'-','');
  insert into public.group_invitations(group_id,token_hash,created_by) values(p_group_id,encode(sha256(convert_to(v_token,'UTF8')),'hex'),auth.uid());
  return v_token;
end $$;
create function public.accept_invitation(p_token text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_inv public.group_invitations;
begin
  perform app_private.require_user();
  if p_token is null or p_token !~ '^[0-9a-f]{64}$' then raise exception 'Invitation unavailable' using errcode='22023'; end if;
  select * into v_inv from public.group_invitations where token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex') for update;
  if not found or v_inv.revoked_at is not null or v_inv.accepted_at is not null or v_inv.expires_at <= now() then raise exception 'Invitation unavailable' using errcode='22023'; end if;
  if app_private.is_member(v_inv.group_id) then raise exception 'Already a member' using errcode='22023'; end if;
  insert into public.group_members(group_id,user_id,role) values(v_inv.group_id,auth.uid(),'member');
  update public.group_invitations set accepted_at=now(),accepted_by=auth.uid() where id=v_inv.id;
  return v_inv.group_id;
end $$;
create function public.revoke_invitation(p_invitation_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare v_group uuid;
begin
  perform app_private.require_user();
  select group_id into v_group from public.group_invitations where id=p_invitation_id;
  if v_group is null or not app_private.is_editor(v_group) then raise exception 'Not authorized' using errcode='42501'; end if;
  update public.group_invitations set revoked_at=coalesce(revoked_at,now()) where id=p_invitation_id;
end $$;
create function public.remove_member(p_group_id uuid,p_user_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare v_role text; v_target_role text;
begin
  perform app_private.require_user();
  v_role := app_private.member_role(p_group_id);
  select role into v_target_role from public.group_members where group_id=p_group_id and user_id=p_user_id for update;
  if v_role is null or v_role not in ('owner','admin') or v_target_role is null or v_target_role='owner' or (v_role='admin' and v_target_role='admin') then raise exception 'Not authorized' using errcode='42501'; end if;
  delete from public.trip_participants p using public.trips t where p.trip_id=t.id and t.group_id=p_group_id and p.user_id=p_user_id;
  delete from public.group_members where group_id=p_group_id and user_id=p_user_id;
end $$;
create function public.set_participation(p_trip_id uuid,p_status text) returns void
language plpgsql security definer set search_path = '' as $$
declare v_group uuid;
begin
  perform app_private.require_user();
  select group_id into v_group from public.trips where id=p_trip_id;
  perform app_private.lock_member(v_group,false);
  if p_status is null or p_status not in ('going','undecided','not_going') then raise exception 'Invalid status' using errcode='22023'; end if;
  insert into public.trip_participants(trip_id,user_id,status) values(p_trip_id,auth.uid(),p_status)
  on conflict (trip_id,user_id) do update set status=excluded.status,updated_at=now();
end $$;

create function public.reorder_stops(p_trip_id uuid,p_stop_ids uuid[],p_expected_version integer) returns integer
language plpgsql security definer set search_path = '' as $$
declare v_version integer; v_count integer;
begin
  perform app_private.require_user();
  if not app_private.trip_editor(p_trip_id) then raise exception 'Not authorized' using errcode='42501'; end if;
  select version into v_version from public.trips where id=p_trip_id for update;
  if p_expected_version is null or v_version is distinct from p_expected_version then raise exception 'Trip changed; refresh before reordering' using errcode='40001'; end if;
  select count(*) into v_count from public.trip_stops where trip_id=p_trip_id;
  if p_stop_ids is null or cardinality(p_stop_ids)<>v_count
    or (select count(distinct x) from unnest(p_stop_ids) x)<>v_count
    or exists(select 1 from unnest(p_stop_ids) x where not exists(select 1 from public.trip_stops s where s.id=x and s.trip_id=p_trip_id))
  then raise exception 'Invalid stop order' using errcode='22023'; end if;
  update public.trip_stops s set position=u.ordinality-1 from unnest(p_stop_ids) with ordinality as u(id,ordinality)
  where s.id=u.id and s.trip_id=p_trip_id and s.position is distinct from u.ordinality-1;
  select version into v_version from public.trips where id=p_trip_id;
  return v_version;
end $$;

create function app_private.allowed_keys(p_object jsonb,p_allowed text[]) returns void
language plpgsql immutable set search_path = '' as $$
begin
  if jsonb_typeof(p_object) is distinct from 'object' then raise exception 'Expected an object' using errcode='22023'; end if;
  if exists(select 1 from jsonb_object_keys(p_object) k where not(k=any(p_allowed))) then raise exception 'Unexpected import field' using errcode='22023'; end if;
end $$;
create function app_private.import_text(p_object jsonb,p_key text,p_max integer,p_required boolean default false) returns text
language plpgsql immutable set search_path = '' as $$
declare v_text text;
begin
  if not(p_object ? p_key) then
    if p_required then raise exception 'Required import field missing' using errcode='22023'; end if;
    return null;
  end if;
  if jsonb_typeof(p_object->p_key) is distinct from 'string' then raise exception 'Invalid import text' using errcode='22023'; end if;
  v_text := p_object->>p_key;
  if length(v_text)>p_max or (p_required and length(btrim(v_text))=0) then raise exception 'Invalid import text length' using errcode='22023'; end if;
  return v_text;
end $$;
create function public.import_private_trip(p_group_id uuid,p_payload jsonb,p_request_id uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  v_id uuid; v_stop_id uuid; v_args jsonb; v_item jsonb; v_trip jsonb; v_name text; v_key text;
  v_currency text; v_timezone text; v_title text; v_description text; v_why text; v_details jsonb; v_trip_details jsonb;
  v_stop_map jsonb := '{}'::jsonb; v_position integer := 0; v_kind text;
begin
  perform app_private.require_user();
  if not app_private.is_editor(p_group_id) then raise exception 'Not authorized' using errcode='42501'; end if;
  perform app_private.lock_member(p_group_id,true);
  if p_payload is null or octet_length(p_payload::text)>2097152 then raise exception 'Import too large or absent' using errcode='22023'; end if;
  perform app_private.allowed_keys(p_payload,array['schema_version','kind','trip','stops','activities','lodgings','transfers']);
  if not(p_payload ?& array['schema_version','kind','trip','stops','activities','lodgings','transfers']) or p_payload->'schema_version' is distinct from '1'::jsonb or p_payload->'kind' is distinct from '"private-trip"'::jsonb then raise exception 'Unsupported import format' using errcode='22023'; end if;
  v_trip := p_payload->'trip';
  perform app_private.allowed_keys(v_trip,array['name','currency','timezone','details']);
  v_name := app_private.import_text(v_trip,'name',120,true);
  v_currency := coalesce(app_private.import_text(v_trip,'currency',3),'EUR');
  v_timezone := coalesce(app_private.import_text(v_trip,'timezone',100),'UTC');
  v_trip_details := coalesce(v_trip->'details','{}'::jsonb);
  if jsonb_typeof(v_trip_details) is distinct from 'object' or octet_length(v_trip_details::text)>524288 then raise exception 'Invalid trip details object' using errcode='22023'; end if;
  if v_currency !~ '^[A-Z]{3}$' then raise exception 'Invalid currency' using errcode='22023'; end if;
  foreach v_kind in array array['stops','activities','lodgings','transfers'] loop
    if jsonb_typeof(p_payload->v_kind) is distinct from 'array' then raise exception 'Expected import array' using errcode='22023'; end if;
    if jsonb_array_length(p_payload->v_kind) > (case v_kind when 'stops' then 100 when 'activities' then 1000 else 200 end) then raise exception 'Too many import records' using errcode='22023'; end if;
  end loop;
  v_args := jsonb_build_object('group_id',p_group_id,'payload',p_payload);
  v_id := app_private.operation_result('import_private_trip',p_request_id,v_args);
  if v_id is not null then return v_id; end if;
  insert into public.trips(group_id,name,currency,timezone,details,created_by) values(p_group_id,btrim(v_name),v_currency,v_timezone,v_trip_details,auth.uid()) returning id into v_id;
  insert into public.trip_participants(trip_id,user_id,status) values(v_id,auth.uid(),'going');
  for v_item in select value from jsonb_array_elements(p_payload->'stops') loop
    perform app_private.allowed_keys(v_item,array['key','name']);
    v_key := app_private.import_text(v_item,'key',100,true);
    v_name := app_private.import_text(v_item,'name',120,true);
    if v_stop_map ? v_key then raise exception 'Duplicate stop key' using errcode='22023'; end if;
    insert into public.trip_stops(trip_id,name,position) values(v_id,btrim(v_name),v_position) returning id into v_stop_id;
    v_stop_map := v_stop_map || jsonb_build_object(v_key,v_stop_id::text);
    v_position := v_position+1;
  end loop;
  foreach v_kind in array array['activities','lodgings','transfers'] loop
    for v_item in select value from jsonb_array_elements(p_payload->v_kind) loop
      perform app_private.allowed_keys(v_item,case when v_kind='activities' then array['title','stop_key','description','why_visit','details'] else array['title','stop_key','description','details'] end);
      v_title := app_private.import_text(v_item,'title',200,true);
      v_description := coalesce(app_private.import_text(v_item,'description',20000),'');
      v_why := coalesce(app_private.import_text(v_item,'why_visit',10000),'');
      v_details := coalesce(v_item->'details','{}'::jsonb);
      if jsonb_typeof(v_details) is distinct from 'object' or octet_length(v_details::text)>102400 then raise exception 'Invalid details object' using errcode='22023'; end if;
      v_stop_id := null;
      if v_item ? 'stop_key' and v_item->'stop_key' <> 'null'::jsonb then
        v_key := app_private.import_text(v_item,'stop_key',100,true);
        if not(v_stop_map ? v_key) then raise exception 'Unknown stop reference' using errcode='22023'; end if;
        v_stop_id := (v_stop_map->>v_key)::uuid;
      end if;
      if v_kind='activities' then
        insert into public.activities(trip_id,stop_id,title,description,why_visit,details,created_by) values(v_id,v_stop_id,btrim(v_title),v_description,v_why,v_details,auth.uid());
      elsif v_kind='lodgings' then
        insert into public.lodgings(trip_id,stop_id,title,description,details,created_by) values(v_id,v_stop_id,btrim(v_title),v_description,v_details,auth.uid());
      else
        insert into public.transfers(trip_id,stop_id,title,description,details,created_by) values(v_id,v_stop_id,btrim(v_title),v_description,v_details,auth.uid());
      end if;
    end loop;
  end loop;
  perform app_private.save_operation('import_private_trip',p_request_id,v_args,v_id);
  return v_id;
end $$;

create function public.create_stop(p_trip_id uuid,p_name text,p_position integer,p_request_id uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_group uuid; v_id uuid; v_args jsonb := jsonb_build_object('trip_id',p_trip_id,'name',p_name,'position',p_position);
begin
  perform app_private.require_user();
  select group_id into v_group from public.trips where id=p_trip_id;
  perform app_private.lock_member(v_group,true);
  v_id := app_private.operation_result('create_stop',p_request_id,v_args);
  if v_id is not null then return v_id; end if;
  insert into public.trip_stops(trip_id,name,position) values(p_trip_id,btrim(p_name),p_position) returning id into v_id;
  perform app_private.save_operation('create_stop',p_request_id,v_args,v_id);
  return v_id;
end $$;

create function public.create_item(p_table text,p_trip_id uuid,p_fields jsonb,p_request_id uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  v_group uuid; v_id uuid; v_args jsonb; v_stop_id uuid;
  v_title text; v_description text; v_why text; v_details jsonb;
begin
  perform app_private.require_user();
  if p_table is null or p_table not in ('activities','lodgings','transfers') then raise exception 'Invalid item table' using errcode='22023'; end if;
  select group_id into v_group from public.trips where id=p_trip_id;
  perform app_private.lock_member(v_group,p_table<>'activities');
  perform app_private.allowed_keys(p_fields,case when p_table='activities' then array['title','description','why_visit','stop_id','details'] else array['title','description','stop_id','details'] end);
  v_title := app_private.import_text(p_fields,'title',200,true);
  v_description := coalesce(app_private.import_text(p_fields,'description',20000),'');
  v_why := coalesce(app_private.import_text(p_fields,'why_visit',10000),'');
  v_details := coalesce(p_fields->'details','{}'::jsonb);
  if jsonb_typeof(v_details) is distinct from 'object' or octet_length(v_details::text)>102400 then raise exception 'Invalid details object' using errcode='22023'; end if;
  if p_fields ? 'stop_id' and p_fields->'stop_id' <> 'null'::jsonb then
    v_stop_id := app_private.import_text(p_fields,'stop_id',36,true)::uuid;
  end if;
  v_args := jsonb_build_object('table',p_table,'trip_id',p_trip_id,'fields',p_fields);
  v_id := app_private.operation_result('create_item',p_request_id,v_args);
  if v_id is not null then return v_id; end if;
  if p_table='activities' then
    insert into public.activities(trip_id,stop_id,title,description,why_visit,details,created_by) values(p_trip_id,v_stop_id,btrim(v_title),v_description,v_why,v_details,auth.uid()) returning id into v_id;
  elsif p_table='lodgings' then
    insert into public.lodgings(trip_id,stop_id,title,description,details,created_by) values(p_trip_id,v_stop_id,btrim(v_title),v_description,v_details,auth.uid()) returning id into v_id;
  else
    insert into public.transfers(trip_id,stop_id,title,description,details,created_by) values(p_trip_id,v_stop_id,btrim(v_title),v_description,v_details,auth.uid()) returning id into v_id;
  end if;
  perform app_private.save_operation('create_item',p_request_id,v_args,v_id);
  return v_id;
end $$;

